"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["58612"],{82519(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.tipo_de_campo_obrigatorio","status":422,"titulo":"O tipo de campo do item \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.item_formulario.tipo_de_campo_obrigatorio","requisitos":[],"oQueAconteceu":["O `tipoDeCampo` de um item do formul\xe1rio, ou de um campo de grupo, est\xe1 vazio ou s\xf3 com espa\xe7os. Os c\xf3digos aceitos s\xe3o: `NUMERO`, `SIM_OU_NAO`, `ESCOLHA_UNICA`, `ESCOLHA_MULTIPLA`, `TEXTO`, `DATA`, `ENDERECO` e `MUNICIPIO`. O c\xf3digo \xe9 conferido letra a letra, e `texto` em min\xfasculas n\xe3o \xe9 `TEXTO`. Um c\xf3digo desconhecido recebe a recusa de [tipo de campo n\xe3o reconhecido](/erros/uniplus.item_formulario.tipo_de_campo_invalido). A mensagem \xe9 \\"O tipo de campo do item \xe9 obrigat\xf3rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].apresentacao.tipoDeCampo` ou, no campo de um grupo, `grupos[g].subitens[j].apresentacao.tipoDeCampo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Cada item recusado tem a pr\xf3pria entrada, junto das demais recusas da forma do item, e o item de forma recusada n\xe3o segue para a confer\xeancia contra o cat\xe1logo de fatos. Nada \xe9 gravado.","A propriedade `tipoDeCampo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. O tipo que existe mas n\xe3o combina com o fato \xe9 outra recusa, a de [tipo de campo incoerente com o dom\xednio do dado](/erros/uniplus.item_formulario.tipo_de_campo_incoerente_com_dominio). Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe em `tipoDeCampo` um dos oito c\xf3digos, em mai\xfasculas, o que combina com o dom\xednio do fato no cat\xe1logo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);